  types?: Array<"PER" | "ORG" | "LOC" | "MISC"> | null;
  /** Default: 0.6. (exclusiveMinimum 0, exclusiveMaximum 1) */
  min_score?: number;
  /** Default: 20. (minimum 1, maximum 500) */
  top?: number;
  /** Default: 20000. (minimum 1, maximum 200000) */
  max_rows?: number;
  /** Save a dataset with the entities found in each row. Default: false. */
